  [Benchmark]
  public string StringBuilderWithAppends()
  {
    StringBuilder builder = new();
    for (int i = 1; i <= Count; ++i)
    {
      builder
        .Append("test")
        .Append(i);
    }
    return builder.ToString();
  }

  [Benchmark]
  public string StringBuilderWithAppendFormat()
  {
    StringBuilder builder = new();
    for (int i = 1; i <= Count; ++i)
    {
      builder.AppendFormat("test{0}", i);
    }
    return builder.ToString();
  }

  [Benchmark]
  public string StringBuilderWithInterpolatedAppend()
  {
    StringBuilder builder = new();
    for (int i = 1; i <= Count; ++i)
    {
      builder.Append($"test{i}");
    }
    return builder.ToString();
  }
